import { realpath } from "node:fs/promises";
import path from "node:path";
import { localFileSystem } from "../filesystem.js";
/**
 * A host directory as a tree rooted at `/`: `/src/a.ts` is `<dir>/src/a.ts`.
 * A path that resolves outside the directory, through `..` or a symlink, is
 * refused. Results and error messages name tree paths, never host paths.
 */
export function hostDirectoryTree(dir) {
    const host = localFileSystem({ cwd: dir, confineToWorkspace: true });
    const roots = realpath(dir).then((real) => [...new Set([real, path.resolve(dir)])], () => [path.resolve(dir)]);
    const toTree = async (hostPath) => {
        for (const root of await roots) {
            const relative = path.relative(root, hostPath);
            if (relative !== ".." &&
                !relative.startsWith(`..${path.sep}`) &&
                !path.isAbsolute(relative)) {
                return relative === "" ? "/" : `/${relative.split(path.sep).join("/")}`;
            }
        }
        return hostPath;
    };
    const scrub = async (error) => {
        if (error instanceof Error) {
            for (const root of await roots) {
                error.message = error.message.split(`${root}${path.sep}`).join("/").split(root).join("/");
            }
            const located = error;
            if (typeof located.path === "string") {
                located.path = await toTree(located.path);
            }
        }
        throw error;
    };
    const guard = async (run) => {
        try {
            return await run();
        }
        catch (error) {
            return scrub(error);
        }
    };
    async function* entries(source) {
        try {
            for await (const entry of source) {
                yield { ...entry, path: await toTree(entry.path) };
            }
        }
        catch (error) {
            await scrub(error);
        }
    }
    async function* matches(source) {
        try {
            for await (const match of source) {
                yield { ...match, path: await toTree(match.path) };
            }
        }
        catch (error) {
            await scrub(error);
        }
    }
    return {
        list: (prefix, options) => entries(host.list(prefix === undefined ? undefined : hostPath(prefix), options)),
        stat: (probe) => guard(() => host.stat(hostPath(probe))),
        read: (file) => guard(() => host.read(hostPath(file))),
        glob: (pattern, globDir, options) => entries(host.glob(pattern, globDir === undefined ? undefined : hostPath(globDir), options)),
        grep: (query) => matches(host.grep(query.path === undefined ? query : { ...query, path: hostPath(query.path) })),
        write: (file, contents) => guard(() => host.write(hostPath(file), contents)),
        delete: (file) => guard(() => host.delete(hostPath(file))),
    };
}
/** Where a confined host workspace is mounted when the agent sets no `workspace`. */
export const DEFAULT_TREE_WORKSPACE = "/workspace";
const FILE_TOOLS = new Set(["read", "grep", "glob", "ls", "edit", "delete"]);
/** Tools a tree cannot back. A tree agent's `tools` drops them. */
const HOST_ONLY_TOOLS = new Set([
    "readlints",
    "applyagentdiff",
    "computeruse",
    "recordscreen",
    "writeshellstdin",
]);
/**
 * Whether a host-disk agent runs on its session workspace as a tree: it is
 * sandboxed, its `tools` grant a file tool, and they grant no shell. Its
 * reads then stay inside the workspace without a shell that could read
 * around them.
 */
export function confinesWorkspaceReads(agent) {
    if (agent.local?.sandbox !== true || agent.tools === undefined) {
        return false;
    }
    const names = agent.tools.map((name) => name.toLowerCase());
    return !names.includes("shell") && names.some((name) => FILE_TOOLS.has(name));
}
/** `tools` without the ones a tree cannot back, and the names it dropped. */
export function treeToolAllowlist(tools) {
    const dropped = tools.filter((name) => HOST_ONLY_TOOLS.has(name.toLowerCase()));
    return { tools: tools.filter((name) => !dropped.includes(name)), dropped };
}
/** A tree path as a path relative to the directory; `..` cannot climb out of `/`. */
function hostPath(treePath) {
    const relative = path.posix.normalize(`/${treePath.replace(/\\/g, "/")}`).slice(1);
    return relative === "" ? "." : relative;
}
